INSERT INTO veiculos (id, modelo, versao, categoria, ano_modelo, ano_fabricacao, quilometragem, motorizacao, transmissao, potencia, aceleracao, portas, combustivel, cor, descricao_exterior, descricao_interior, preco, status) VALUES
(1, 'Série 1', '118i M Sport', 'Hatch Premium', 2024, 2024, 0, '1.5 Turbo', 'Automático 7 marchas', '140 cv / 22,4 kgfm', '8,5 s', 4, 'Gasolina', 'Branco Alpino', 'O autêntico prazer de dirigir em sua forma mais compacta. A icônica grade duplo-rim e as grandes entradas de ar no para-choque M Sport enfatizam seu caráter atlético e dinâmico desde o primeiro olhar.', 'Cabine voltada para o condutor com volante M em couro e bancos esportivos. O sistema de iluminação ambiente cria uma atmosfera moderna, enquanto a conectividade de ponta garante que você esteja sempre no controle.', 239000.00, 'Disponível');
