INSERT INTO veiculos (id, modelo, versao, categoria, ano_modelo, ano_fabricacao, quilometragem, motorizacao, transmissao, potencia, aceleracao, portas, combustivel, cor, descricao_exterior, descricao_interior, preco, status) VALUES
(2, 'Série 2', '218i Gran Coupé M Sport', 'Gran Coupé', 2024, 2024, 0, '1.5 Turbo', 'Automático 7 marchas', '140 cv / 22,4 kgfm', '8,7 s', 4, 'Gasolina', 'Preto Safira', 'A silhueta ousada do Gran Coupé rompe convenções. As portas sem moldura nos vidros e a linha de teto descendente fluem até as lanternas afiladas na traseira, criando um perfil inconfundível.', 'Elegância subversiva no interior. O acabamento refinado se une ao BMW Live Cockpit Professional, entregando uma experiência digital fluida através de duas telas imersivas de alta resolução.', 259000.00, 'Disponível');
