INSERT INTO veiculos (id, modelo, versao, categoria, ano_modelo, ano_fabricacao, quilometragem, motorizacao, transmissao, potencia, aceleracao, portas, combustivel, cor, descricao_exterior, descricao_interior, preco, status) VALUES
(3, 'Série 3', '320i M Sport', 'Sedan Esportivo', 2024, 2024, 0, '2.0 Turbo', 'Automático 8 marchas', '184 cv / 30,6 kgfm', '7,1 s', 4, 'Gasolina', 'Cinza Brooklyn', 'O ícone definitivo dos sedans esportivos. O design exterior é a pura expressão da esportividade, com linhas precisas, superfícies esculpidas e faróis full LED agressivos que dominam as estradas.', 'O interior é totalmente focado no motorista. O BMW Curved Display oferece controle intuitivo, enquanto os bancos esportivos garantem conforto e estabilidade em curvas mais acentuadas.', 320000.00, 'Disponível');
