INSERT INTO veiculos (id, modelo, versao, categoria, ano_modelo, ano_fabricacao, quilometragem, motorizacao, transmissao, potencia, aceleracao, portas, combustivel, cor, descricao_exterior, descricao_interior, preco, status) VALUES
(4, 'Série 4', '430i Cabrio M Sport', 'Conversível', 2024, 2024, 0, '2.0 Turbo', 'Automático 8 marchas', '258 cv / 40,8 kgfm', '6,2 s', 2, 'Gasolina', 'Azul Portimao', 'Liberdade sem limites. A grade vertical proeminente presta homenagem aos clássicos, enquanto a capota de tecido acústico recolhe em segundos, revelando linhas elegantes e provocantes.', 'Experimente a emoção de dirigir ao ar livre sem abrir mão do luxo. Materiais requintados, aquecedores de pescoço integrados e som Harman Kardon tornam cada viagem inesquecível.', 470000.00, 'Disponível');
