INSERT INTO veiculos (id, modelo, versao, categoria, ano_modelo, ano_fabricacao, quilometragem, motorizacao, transmissao, potencia, aceleracao, portas, combustivel, cor, descricao_exterior, descricao_interior, preco, status) VALUES
(5, 'Série 5', '530e M Sport', 'Sedan Executivo', 2024, 2024, 0, '2.0 Híbrido Plug-in', 'Automático 8 marchas', '292 cv / 42,8 kgfm', '5,9 s', 4, 'Híbrido', 'Preto Carbono', 'Presença executiva elevada pela tecnologia. O design clássico e sofisticado de três volumes encontra detalhes aerodinâmicos do pacote M, unindo a tradição à eficiência do futuro eletrificado.', 'Santuário de produtividade e conforto. Acabamento primoroso, isolamento acústico supremo e assistentes de condução semi-autônoma de nível superior para viagens sem nenhum estresse.', 490000.00, 'Disponível');
